// === Tab: mySketch.js ===
let num = 52; 
let s = 2.5; // 稍微调大了一点点，方便在网页端观察
let reflex = 0.2; 
let aperture = 20; 

let bg, fg1, fg2;
let t = 0;
let aa = [];
let bb = [];
let transition = 0;

let song;
let amp;

function preload() {
  // 在此处替换为你的 MP4 或 MP3 链接
  // 也可以在 OpenProcessing 的 Files 栏上传后直接写文件名
  song = loadSound('https://openprocessing-assets.s3.amazonaws.com/files/650/417271/YourAudioFile.mp3'); 
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();

  bg = color(0);
  fg1 = color(66, 245, 188);
  fg2 = color(148, 252, 3);

  aa = new Array(8);
  bb = new Array(8);
  resetWave();

  // 音频初始化
  amp = new p5.Amplitude();
  song.play();
  song.loop();
}

function resetWave() {
  for (let i = 0; i < 8; i++) {
    let v = random(1, 10);
    bb[i] = aa[i] || 0;
    aa[i] = random(2) < 1 ? v : -v;
  }
  transition = 1;
}

function draw() {
  // 获取当前音频的振幅 (0.0 到 1.0)
  let level = amp.getLevel();

  // 1. 声音交互：如果声音很大，则触发参数重置（类似点击效果）
  if (level > 0.3 && transition < 0.1) {
    resetWave();
  }

  t += 0.0008; 
  background(bg);
  transition *= (1 - reflex);

  // 2. 声音交互：让波浪的高度受音量实时缩放
  let audioBoost = map(level, 0, 0.5, 0.5, 2.5);

  for (let v = 0; v < num; v++) {
    for (let u = 0; u < num; u++) {

      // 原有的波浪计算
      let h = 42 * audioBoost
        * sin((aa[0] * u - aa[1] * v) / num + 4.2 * aa[4] * t + aa[6])
        * cos((aa[2] * v + aa[3] * u) / num + aa[5] * t + aa[7]);

      let h2 = 42 * audioBoost
        * sin((bb[0] * u - bb[1] * v) / num + 4.2 * bb[4] * t + bb[6])
        * cos((bb[2] * v + bb[3] * u) / num + bb[5] * t + bb[7]);

      h = lerp(h, h2, transition);

      // 坐标转换逻辑
      let u1 = u / num * 2 - 1;
      let v1 = v / num * 2 - 1;
      let u2 = cos(t) * u1 + sin(t) * v1;
      let v2 = sin(t) * u1 - cos(t) * v1; 
      let u3 = u2 / 2 + 0.5;
      let v3 = v2 / 2 + 0.5;

      let side = max(width, height);
      let x = u3 * side;
      let y = v3 * side;
      let a = x - y;
      let b = x + y;

      push();
      translate(width / 2, -200);

      let distVal = 1.5 - b / 2 / height - h / 500;
      scale(atan(1 / distVal) * 3.4);
      translate(-width / 2, -height / 3.5);

      let blur = (1 - distVal) * aperture;

      // 颜色混合
      let c = lerpColor(fg1, fg2, constrain(map(blur, -aperture/3, aperture/2, 0, 1), 0, 1));
      let alpha = min(s * 255 / max(sq(blur / 2) * 2, 1), 128);
      fill(red(c), green(c), blue(c), alpha);

      translate(0, -h); 
      ellipse(a / 4 + width / 2, b / 42 + height / 2, max(abs(blur), s));
      pop();
    }
  }
}

// 备用的点击重新播放（防止浏览器自动播放限制）
function mousePressed() {
  if (song.isPlaying()) {
    song.pause();
  } else {
    song.play();
  }
}

